     1	import type { CookieSerializeOptions } from "cookie-es";
     2	import type { H3Event, HTTPEvent } from "../event.ts";
     3	import { parseCookie, serializeCookie, parseSetCookie } from "cookie-es";
     4	import { validateData } from "./internal/validate.ts";
     5	import type { StandardSchemaV1, FailureResult, InferOutput } from "./internal/standard-schema.ts";
     6	import type { ValidateResult, OnValidateError } from "./internal/validate.ts";
     7	import type { ErrorDetails } from "../error.ts";
     8	import { HTTPError } from "../error.ts";
     9	
    10	const CHUNKED_COOKIE = "__chunked__";
    11	
    12	// The limit is approximately 4KB, but may vary by browser and server. We leave some room to be safe.
    13	const CHUNKS_MAX_LENGTH = 4000;
    14	
    15	/**
    16	 * Parse the request to get HTTP Cookie header string and returning an object of all cookie name-value pairs.
    17	 * @param event {HTTPEvent} H3 event or req passed by h3 handler
    18	 * @returns Object of cookie name-value pairs
    19	 * ```ts
    20	 * const cookies = parseCookies(event)
    21	 * ```
    22	 */
    23	export function parseCookies(event: HTTPEvent): Record<string, string | undefined> {
    24	  return parseCookie(event.req.headers.get("cookie") || "");
    25	}
    26	
    27	/**
    28	 * Get and validate all cookies using a Standard Schema or custom validator.
    29	 *
    30	 * @example
    31	 * app.get("/", async (event) => {
    32	 *   const cookies = await getValidatedCookies(event, z.object({
    33	 *     session: z.string(),
    34	 *     theme: z.enum(["light", "dark"]).optional(),
    35	 *   }));
    36	 * });
    37	 */
    38	export function getValidatedCookies<Event extends HTTPEvent, S extends StandardSchemaV1<any, any>>(
    39	  event: Event,
    40	  validate: S,
    41	  options?: { onError?: (result: FailureResult) => ErrorDetails },
    42	): Promise<InferOutput<S>>;
    43	export function getValidatedCookies<Event extends HTTPEvent, OutputT>(
    44	  event: Event,
    45	  validate: (
    46	    data: Record<string, string | undefined>,
    47	  ) => ValidateResult<OutputT> | Promise<ValidateResult<OutputT>>,
    48	  options?: { onError?: () => ErrorDetails },
    49	): Promise<OutputT>;
    50	export function getValidatedCookies(
    51	  event: HTTPEvent,
    52	  validate: any,
    53	  options?: { onError?: OnValidateError },
    54	): Promise<any> {
    55	  const cookies = parseCookies(event);
    56	  return validateData(cookies, validate, options);
    57	}
    58	
    59	/**
    60	 * Get a cookie value by name.
    61	 * @param event {HTTPEvent} H3 event or req passed by h3 handler
    62	 * @param name Name of the cookie to get
    63	 * @returns {*} Value of the cookie (String or undefined)
    64	 * ```ts
    65	 * const authorization = getCookie(request, 'Authorization')
    66	 * ```
    67	 */
    68	export function getCookie(event: HTTPEvent, name: string): string | undefined {
    69	  return parseCookies(event)[name];
    70	}
    71	
    72	/**
    73	 * Set a cookie value by name.
    74	 * @param event {H3Event} H3 event or res passed by h3 handler
    75	 * @param name Name of the cookie to set
    76	 * @param value Value of the cookie to set
    77	 * @param options {CookieSerializeOptions} Options for serializing the cookie
    78	 * ```ts
    79	 * setCookie(res, 'Authorization', '1234567')
    80	 * ```
    81	 */
    82	export function setCookie(
    83	  event: H3Event,
    84	  name: string,
    85	  value: string,
