  describe("extraUnsealPasswords", () => {
    const OLD_PASSWORD = "old-password-old-password-old-password-1";
    const NEW_PASSWORD = "new-password-new-password-new-password-2";
    const rotated: SessionConfig = {
      name: "h3-rot",
      password: NEW_PASSWORD,
      extraUnsealPasswords: [OLD_PASSWORD],
    };
    const sealedWith = (password: string) =>
      seal({ id: "rot-1", createdAt: Date.now(), data: { foo: "old" } }, password, sealDefaults);
    const cookieValue = (res: Response, name: string) =>
      decodeURIComponent(
        res.headers
          .getSetCookie()
          .find((c) => c.startsWith(`${name}=`))!
          .match(/=([^;]+)/)![1],
      );

    beforeEach(() => {
      t.app.get("/rot", async (event) => {
        const session = await getSession(event, rotated);
        return { id: session.id, data: session.data };
      });
      t.app.post("/rot-write", async (event) => {
        const session = await updateSession(event, rotated, { foo: "new" });
        return { id: session.id };
      });
    });

    it("opens a cookie sealed with an extra password and keeps its id and data", async () => {
      const sealed = await sealedWith(OLD_PASSWORD);
      const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "rot-1", data: { foo: "old" } });
    });

    it("reseals a read-only session opened with an extra password using password", async () => {
      const sealed = await sealedWith(OLD_PASSWORD);
      const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
      const resealed = cookieValue(res, "h3-rot");
      expect(await unseal(resealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "rot-1",
        data: { foo: "old" },
      });
      await expect(unseal(resealed, OLD_PASSWORD, sealDefaults)).rejects.toThrow();
    });

    it("seals a write made after an extra-password read with password only", async () => {
      const sealed = await sealedWith(OLD_PASSWORD);
      const res = await t.fetch("/rot-write", {
        method: "POST",
        headers: { Cookie: `h3-rot=${sealed}` },
      });
      expect(await res.json()).toMatchObject({ id: "rot-1" });
      const written = cookieValue(res, "h3-rot");
      expect(await unseal(written, NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "rot-1",
        data: { foo: "new" },
      });
      await expect(unseal(written, OLD_PASSWORD, sealDefaults)).rejects.toThrow();
    });

    it("reseals a legacy cookie opened with an extra password once, with password", async () => {
      const legacySealed = await seal(
        { id: "rot-1", createdAt: Date.now(), data: { foo: "old" } },
        OLD_PASSWORD,
        {
          ...sealDefaults,
          encryption: { ...sealDefaults.encryption, iterations: 1 },
          integrity: { ...sealDefaults.integrity, iterations: 1 },
        },
      );
      const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${legacySealed}` } });
      expect(await res.json()).toMatchObject({ id: "rot-1", data: { foo: "old" } });
      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      expect(await unseal(cookieValue(res, "h3-rot"), NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "rot-1",
      });
    });

    it("does not reseal a cookie opened with the current password", async () => {
      const sealed = await seal(
        { id: "rot-1", createdAt: Date.now(), data: { foo: "new" } },
        NEW_PASSWORD,
        sealDefaults,
      );
      const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "rot-1", data: { foo: "new" } });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("keeps a cookie sealed with an unknown password out of the session", async () => {
      const sealed = await seal(
        { id: "rot-1", createdAt: Date.now(), data: { foo: "old" } },
        "unknown-password-unknown-password-0003",
        sealDefaults,
      );
      const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
      const body = await res.json();
      expect(body.id).not.toBe("rot-1");
      expect(body.data).toEqual({});
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("does not read a session that expired under maxAge, even when sealed with an extra password", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        t.app.get("/rot-max", async (event) => {
          const session = await getSession(event, { ...rotated, maxAge: 60 });
          return { id: session.id };
        });
        const sealed = await seal(
          { id: "rot-1", createdAt: t0 - 120_000, data: {} },
          OLD_PASSWORD,
          sealDefaults,
        );
        const res = await t.fetch("/rot-max", { headers: { Cookie: `h3-rot=${sealed}` } });
        expect((await res.json()).id).not.toBe("rot-1");
      } finally {
        vi.useRealTimers();
      }
    });

    it("does not read a session that expired under idleTimeout, even when sealed with an extra password", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        t.app.get("/rot-idle", async (event) => {
          const session = await getSession(event, { ...rotated, maxAge: 3600, idleTimeout: 60 });
          return { id: session.id };
        });
        const sealed = await seal(
          { id: "rot-1", createdAt: t0 - 120_000, data: {} },
          OLD_PASSWORD,
          sealDefaults,
        );
        const res = await t.fetch("/rot-idle", { headers: { Cookie: `h3-rot=${sealed}` } });
        expect((await res.json()).id).not.toBe("rot-1");
      } finally {
        vi.useRealTimers();
      }
    });

    it("does not reseal a session read from the session header, since no cookie can be sent back", async () => {
      const sealed = await sealedWith(OLD_PASSWORD);
      const res = await t.fetch("/rot", { headers: { "x-h3-rot-session": sealed } });
      expect(await res.json()).toMatchObject({ id: "rot-1", data: { foo: "old" } });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });
  });
});

