  vi.mocked(seal).mockClear();
});

describe("extraUnsealPasswords: order of attempts", () => {
  // Protects RF-02: the current password is tried first, then the extras in order.
  it("tries password first, then the extras in the order given", async () => {
    const sealed = await sealWith(UNKNOWN);
    vi.mocked(unseal).mockClear();

    await getSession(
      eventWithCookie(sealed),
      sessionConfig({ extraUnsealPasswords: [EXTRA_1, EXTRA_2] }),
    );

    expect(triedPasswords()).toEqual([PASSWORD, EXTRA_1, EXTRA_2]);
  });

  // Protects RF-02: the first password that opens the seal is the last one tried.
  it("stops at the first password that opens the cookie", async () => {
    const sealed = await sealWith(EXTRA_1);
    vi.mocked(unseal).mockClear();

    const session = await getSession(
      eventWithCookie(sealed),
      sessionConfig({ extraUnsealPasswords: [EXTRA_1, EXTRA_2] }),
    );

    expect(session.id).toBe("unit-1");
    expect(triedPasswords()).toEqual([PASSWORD, EXTRA_1]);
  });

  // Protects D-03: a candidate that fails for its own reason (too short) must
  // not stop the attempts that follow it.
  it("keeps trying after a candidate fails for its own reason", async () => {
    const sealed = await sealWith(EXTRA_1);
    vi.mocked(unseal).mockClear();

    const session = await getSession(
      eventWithCookie(sealed),
      sessionConfig({ extraUnsealPasswords: ["too-short", EXTRA_1] }),
    );

    expect(session.id).toBe("unit-1");
    expect(triedPasswords()).toEqual([PASSWORD, "too-short", EXTRA_1]);
  });
});

describe("extraUnsealPasswords: sealing", () => {
  // Protects RF-03: sealing never falls back to an extra password.
  it("seals with password, so the result does not open with an extra password", async () => {
    const sealed = await sealSession(mockEvent("/"), sessionConfig({ extraUnsealPasswords: [EXTRA_1] }));

    await expect(unseal(sealed, PASSWORD, sealDefaults)).resolves.toMatchObject({ id: expect.any(String) });
    await expect(unseal(sealed, EXTRA_1, sealDefaults)).rejects.toThrow();
  });
});

describe("extraUnsealPasswords: reseal after opening with an extra", () => {
  // Protects D-04: opening with an extra password reseals exactly once.
  it("reseals a modern cookie opened with an extra password exactly once", async () => {
    const sealed = await sealWith(EXTRA_1);
    vi.mocked(seal).mockClear();

    await getSession(eventWithCookie(sealed), sessionConfig({ extraUnsealPasswords: [EXTRA_1] }));

    expect(vi.mocked(seal).mock.calls).toHaveLength(1);
    expect(vi.mocked(seal).mock.calls[0][1]).toBe(PASSWORD);
  });

  // Protects RF-05 and D-04: a legacy cookie opened with an extra is resealed once, with password.
  it("reseals a legacy cookie opened with an extra password exactly once", async () => {
    const legacySealed = await seal(
      { id: "unit-1", createdAt: Date.now(), data: {} },
      EXTRA_1,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );
    vi.mocked(seal).mockClear();

    const session = await getSession(
      eventWithCookie(legacySealed),
      sessionConfig({ legacySealFallback: true, extraUnsealPasswords: [EXTRA_1] }),
    );

    expect(session.id).toBe("unit-1");
    expect(vi.mocked(seal).mock.calls).toHaveLength(1);
    expect(vi.mocked(seal).mock.calls[0][1]).toBe(PASSWORD);
  });

  // Protects D-04 and the PRD's reliability rule: a failed reseal must not reject the read.
  it("resolves the read when the reseal after an extra-password open fails", async () => {
    const sealed = await sealWith(EXTRA_1);
    vi.mocked(seal).mockRejectedValueOnce(new Error("seal failed"));

    const session = await getSession(
      eventWithCookie(sealed),
      sessionConfig({ extraUnsealPasswords: [EXTRA_1] }),
    );

    expect(session.id).toBe("unit-1");
    expect(session.data).toEqual({ foo: "bar" });
  });
});

describe("extraUnsealPasswords: failure", () => {
  // Regression guard for RF-08 (passes before and after the change): when no
  // password opens the cookie, the request gets a new session and no error.
  it("treats the request as a new session when no password opens the cookie", async () => {
    const sealed = await sealWith(UNKNOWN);

    const session = await getSession(
      eventWithCookie(sealed),
      sessionConfig({ extraUnsealPasswords: [EXTRA_1] }),
    );

    expect(session.id).not.toBe("unit-1");
    expect(session.data).toEqual({});
  });

  // Regression guard (passes before and after the change): with a single
  // password, unsealSession keeps throwing the same error as before.
  it("throws the first candidate's error from unsealSession when nothing opens", async () => {
    const sealed = await sealWith(UNKNOWN);

    await expect(unsealSession(mockEvent("/"), sessionConfig(), sealed)).rejects.toThrow(
      "Bad hmac value",
    );
  });
});

